// Preenchimento da página com os dados acima.
function elemento(id) {
    return document.getElementById(id);
}

function adicionarContato(texto, endereco, destaque = false) {
    if (!endereco) return;

    const link = document.createElement('a');
    link.className = destaque ? 'botao primario' : 'botao secundario';
    link.textContent = texto;
    link.href = endereco;
    elemento('contatos').appendChild(link);
}

function linkWhatsApp(numero) {
    const digitos = numero.replace(/\D/g, '');
    if (/^\d{10,11}$/.test(digitos)) return 'https://wa.me/55' + digitos;
    if (/^55\d{10,11}$/.test(digitos)) return 'https://wa.me/' + digitos;
    return '';
}

function adicionarRegistro(lista, titulo, metadados, descricao = '', topicos = []) {
    if (!titulo) return;

    const registro = document.createElement('li');
    registro.className = 'registro';

    const nome = document.createElement('h3');
    nome.textContent = titulo;
    registro.appendChild(nome);

    if (metadados) {
        const detalhe = document.createElement('p');
        detalhe.className = 'metadados';
        detalhe.textContent = metadados;
        registro.appendChild(detalhe);
    }

    if (descricao) {
        const paragrafo = document.createElement('p');
        paragrafo.textContent = descricao;
        registro.appendChild(paragrafo);
    }

    if (topicos.length) {
        const listaTopicos = document.createElement('ul');
        listaTopicos.className = 'responsabilidades';

        for (const topico of topicos) {
            const item = document.createElement('li');
            item.textContent = topico;
            listaTopicos.appendChild(item);
        }

        registro.appendChild(listaTopicos);
    }

    elemento(lista).appendChild(registro);
}

function formatarData(data) {
    if (!data) return '';

    const [ano, mes] = data.split('-');
    return mes ? mes + '/' + ano : ano;
}

function juntarDetalhes(...detalhes) {
    return detalhes.filter(Boolean).join(' · ');
}

function mostrarCurriculo(cv) {
    const pessoa = cv.personalInformation;

    document.title = pessoa.fullName + ' | Portfólio profissional';
    elemento('nome').textContent = pessoa.fullName;
    elemento('titulo').textContent = pessoa.professionalTitle;
    elemento('cidade').textContent = juntarDetalhes(pessoa.location.city, pessoa.location.state);

    if (pessoa.profilePhoto) {
        elemento('foto').src = pessoa.profilePhoto;
        elemento('retrato').hidden = false;
    }

    adicionarContato('WhatsApp', linkWhatsApp(pessoa.whatsapp), true);
    adicionarContato('E-mail', pessoa.email && 'mailto:' + pessoa.email);
    adicionarContato('LinkedIn', pessoa.linkedin);
    adicionarContato('GitHub', pessoa.github);

    elemento('resumo').textContent = cv.professionalSummary.description;
    elemento('objetivo').textContent = cv.professionalSummary.careerObjective;
    elemento('disponibilidade').textContent = cv.additionalInformation.availability;

    for (const trabalho of cv.professionalExperience) {
        const periodo = [
            formatarData(trabalho.startDate),
            trabalho.current ? 'Atual' : formatarData(trabalho.endDate)
        ].filter(Boolean).join(' a ');
        const detalhes = juntarDetalhes(trabalho.company, trabalho.employmentType, trabalho.location, periodo);

        adicionarRegistro('experiencia', trabalho.position, detalhes, trabalho.description, [
            ...trabalho.responsibilities,
            ...trabalho.achievements
        ]);
    }

    for (const curso of cv.education) {
        const inicio = formatarData(curso.startDate);
        const fim = formatarData(curso.endDate);
        const periodo = juntarDetalhes(
            inicio && 'Início em ' + inicio,
            fim && (curso.current ? 'Previsão de conclusão em ' : 'Conclusão em ') + fim
        );
        adicionarRegistro('formacao', curso.degree, juntarDetalhes(curso.institution, periodo), curso.description);
    }

    const competencias = [
        ...cv.skills.technical.filter((item) => item.name).map((item) => juntarDetalhes(item.name, item.level)),
        ...cv.skills.tools,
        ...cv.skills.behavioral
    ];

    for (const competencia of competencias.filter(Boolean)) {
        const item = document.createElement('li');
        item.textContent = competencia;
        elemento('habilidades').appendChild(item);
    }

    for (const curso of cv.courses) {
        adicionarRegistro('cursos', curso.name, juntarDetalhes(curso.institution, formatarData(curso.completionDate)));
    }

    for (const idioma of cv.languages) {
        adicionarRegistro('idiomas', idioma.name, idioma.proficiency);
    }
}

mostrarCurriculo(dados.cv);
